    #[test]
    fn shared_indirect_annots_array_is_copied_on_write_x7() {
        // Two pages reference the SAME indirect /Annots array (object 6).
        // Annotating page 0 must NOT annotate page 1.
        let bytes = build(
            &[
                "<< /Type /Catalog /Pages 2 0 R >>",
                "<< /Type /Pages /Kids [3 0 R 4 0 R] /Count 2 /MediaBox [0 0 300 300] \
                 /Resources << >> >>",
                "<< /Type /Page /Parent 2 0 R /Annots 6 0 R >>",
                "<< /Type /Page /Parent 2 0 R /Annots 6 0 R >>",
                "<< /Type /Annot /Subtype /Text /Rect [0 0 5 5] >>",
                "[5 0 R]",
            ],
            "",
        );
        let mut s = session(bytes);
        s.add_markup(0, &square_spec()).unwrap();

        // Page 0 (obj 3) now points at a NEW array with two entries.
        let Some(Object::Dict(p0)) = s.value(ObjId::new(3, 0)) else {
            panic!("p0");
        };
        let Some(Object::Reference(p0_arr)) = p0.get(b"Annots") else {
            panic!("p0 annots ref");
        };
        assert_ne!(*p0_arr, ObjId::new(6, 0), "page 0 was repointed (COW)");

        // Page 1 (obj 4) still points at the ORIGINAL array (obj 6), which
        // still has exactly its one original entry — unperturbed.
        let Some(Object::Dict(p1)) = s.value(ObjId::new(4, 0)) else {
            panic!("p1");
        };
        assert_eq!(
            p1.get(b"Annots").unwrap().as_reference(),
            Some(ObjId::new(6, 0))
        );
        let Some(Object::Array(orig)) = s.value(ObjId::new(6, 0)) else {
            panic!("orig array");
        };
        assert_eq!(orig.len(), 1, "the shared array must be untouched");
    }

    #[test]
    fn sole_owner_indirect_annots_array_is_edited_in_place() {
        let bytes = build(
            &[
                "<< /Type /Catalog /Pages 2 0 R >>",
                "<< /Type /Pages /Kids [3 0 R] /Count 1 /MediaBox [0 0 300 300] \
                 /Resources << >> >>",
                "<< /Type /Page /Parent 2 0 R /Annots 5 0 R >>",
                "[]",
            ],
            "",
        );
        let mut s = session(bytes);
        s.add_markup(0, &square_spec()).unwrap();
        // The array object (obj 5) gained the entry; the page dict is
        // unchanged (still references obj 5) — no COW.
        let Some(Object::Array(arr)) = s.value(ObjId::new(5, 0)) else {
            panic!("array");
        };
        assert_eq!(arr.len(), 1);
    }

    // ---- reorder_annotations ------------------------------------------

    /// One page, four indirect annotations: two widgets (4, 5), a Link (6)
    /// and a Text note (7). `annots` is the page's `/Annots` value verbatim
    /// — an inline array, or `8 0 R` for the indirect array object 8 holds.
    fn reorder_fixture(page_extra: &str, annots: &str) -> Vec<u8> {
        build(
            &[
                "<< /Type /Catalog /Pages 2 0 R >>",
                "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
                &format!(
                    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 300] /Resources << >> \
                     /Annots {annots} {page_extra} >>"
                ),
                "<< /Type /Annot /Subtype /Widget /FT /Tx /T (a) /Rect [0 0 10 10] >>",
                "<< /Type /Annot /Subtype /Widget /FT /Tx /T (b) /Rect [20 0 30 10] >>",
                "<< /Type /Annot /Subtype /Link /Rect [40 0 50 10] >>",
                "<< /Type /Annot /Subtype /Text /Rect [60 0 70 10] >>",
                "[4 0 R 5 0 R 6 0 R 7 0 R]",
            ],
            "",
        )
    }

    fn id(n: u32) -> ObjId {
        ObjId::new(n, 0)
    }

    fn annots_of(s: &EditSession, page: ObjId) -> Vec<Option<ObjId>> {
        let Some(Object::Dict(p)) = s.value(page) else {
            panic!("page");
        };
        let arr = match p.get(b"Annots") {
            Some(Object::Array(a)) => a.clone(),
            Some(Object::Reference(r)) => match s.value(*r) {
                Some(Object::Array(a)) => a.clone(),
                other => panic!("annots ref -> {other:?}"),
            },
            other => panic!("annots {other:?}"),
        };
        arr.iter().map(Object::as_reference).collect()
    }

    #[test]
    fn reorder_annotations_permutes_an_inline_array_in_one_command() {
        let mut s = session(reorder_fixture("", "[4 0 R 5 0 R 6 0 R 7 0 R]"));
        let out = s
            .reorder_annotations(0, &[id(5), id(4), id(6), id(7)])
            .unwrap();
        assert_eq!(out.entries, 4);
        assert_eq!(out.moved, 2, "two references changed index");
        assert_eq!(out.non_widgets_moved, 0, "both movers are widgets");
        assert_eq!(out.pinned, 0);
        assert_eq!(out.tabs, PageTabs::Absent);
        assert!(!out.array_copied);
        assert_eq!(
            annots_of(&s, id(3)),
            vec![Some(id(5)), Some(id(4)), Some(id(6)), Some(id(7))]
        );
        // One undo entry, labelled with the count; undo restores the order.
        assert_eq!(s.undo(), Some(CommandKind::ReorderAnnotations { count: 2 }));
        assert_eq!(
            annots_of(&s, id(3)),
            vec![Some(id(4)), Some(id(5)), Some(id(6)), Some(id(7))]
        );
        assert!(!s.can_undo());
        assert!(s.dirty_set().is_empty(), "undo leaves nothing to save");
    }

    #[test]
    fn reorder_annotations_moves_references_and_nothing_else() {
        // The whole request: no annotation dictionary is touched. The dirty
        // set after a reorder is exactly ONE object -- the page -- and every
        // annotation object is what it was.
        let mut s = session(reorder_fixture("", "[4 0 R 5 0 R 6 0 R 7 0 R]"));
        let before: Vec<Option<Object>> = (4..=7).map(|n| s.value(id(n)).cloned()).collect();
        s.reorder_annotations(0, &[id(7), id(6), id(5), id(4)])
            .unwrap();
        let dirty = s.dirty_set();
        assert_eq!(dirty.len(), 1, "only the page dictionary changed");
        let after: Vec<Option<Object>> = (4..=7).map(|n| s.value(id(n)).cloned()).collect();
        assert_eq!(before, after, "annotation objects are untouched");
    }

    #[test]
    fn reorder_annotations_counts_non_widgets_that_moved() {
        let mut s = session(reorder_fixture("", "[4 0 R 5 0 R 6 0 R 7 0 R]"));
        // Move the Link (6) to the front: 6, 4, 5 all change index; 7 stays.
        let out = s
            .reorder_annotations(0, &[id(6), id(4), id(5), id(7)])
            .unwrap();
        assert_eq!(out.moved, 3);
        assert_eq!(
            out.non_widgets_moved, 1,
            "the Link is the one non-widget that moved"
        );
    }

    #[test]
    fn reorder_annotations_identity_records_nothing() {
        let mut s = session(reorder_fixture("", "[4 0 R 5 0 R 6 0 R 7 0 R]"));
        let out = s
            .reorder_annotations(0, &[id(4), id(5), id(6), id(7)])
            .unwrap();
        assert_eq!(out.moved, 0);
        assert!(!s.is_modified());
        assert!(!s.can_undo());
    }

    #[test]
    fn reorder_annotations_refuses_a_non_permutation_and_names_the_ids() {
        let mut s = session(reorder_fixture("", "[4 0 R 5 0 R 6 0 R 7 0 R]"));
        // Missing 7, unknown 99, repeated 4.
        let err = s
            .reorder_annotations(0, &[id(4), id(4), id(5), id(6), id(99)])
            .unwrap_err();
        match err {
            EditError::AnnotsNotAPermutation {
                page_index,
                expected,
                listed,
                missing,
                unknown,
                repeated,
            } => {
                assert_eq!(page_index, 0);
                assert_eq!(expected, 4);
                assert_eq!(listed, 5);
                assert_eq!(missing, vec![id(7)]);
                assert_eq!(unknown, vec![id(99)]);
                assert_eq!(repeated, vec![id(4)]);
            }
            other => panic!("wrong error: {other:?}"),
        }
        assert!(!s.is_modified(), "a refusal changes nothing");
    }

    #[test]
    fn reorder_annotations_refuses_an_array_with_a_duplicate_reference() {
        let mut s = session(reorder_fixture("", "[4 0 R 5 0 R 5 0 R 6 0 R 7 0 R]"));
        let err = s
            .reorder_annotations(0, &[id(7), id(6), id(5), id(4)])
            .unwrap_err();
        assert!(
            matches!(
                err,
                EditError::AnnotsDuplicateReference { page_index: 0, id: d } if d == id(5)
            ),
            "{err:?}"
        );
    }

    #[test]
    fn reorder_annotations_pins_direct_entries_and_discloses_them() {
        // A direct dictionary at index 1 has no id; it must stay at index 1
        // while the references flow around it.
        let mut s = session(reorder_fixture(
            "",
            "[4 0 R << /Type /Annot /Subtype /Square /Rect [0 0 1 1] >> 5 0 R 6 0 R 7 0 R]",
        ));
        let out = s
            .reorder_annotations(0, &[id(7), id(6), id(5), id(4)])
            .unwrap();
        assert_eq!(out.entries, 5);
        assert_eq!(out.pinned, 1);
        assert_eq!(out.moved, 4);
        assert_eq!(
            annots_of(&s, id(3)),
            vec![Some(id(7)), None, Some(id(6)), Some(id(5)), Some(id(4))]
        );
    }

    #[test]
    fn reorder_annotations_reads_tabs_and_does_not_write_it() {
        for (extra, expect) in [
            ("/Tabs /S", PageTabs::Structure),
            ("/Tabs /R", PageTabs::Row),
            ("/Tabs /C", PageTabs::Column),
            ("/Tabs /A", PageTabs::ArrayOrder),
            ("/Tabs /W", PageTabs::WidgetOrder),
            ("/Tabs /Q", PageTabs::Other("Q".to_owned())),
            ("", PageTabs::Absent),
        ] {
            let mut s = session(reorder_fixture(extra, "[4 0 R 5 0 R 6 0 R 7 0 R]"));
            let out = s
                .reorder_annotations(0, &[id(5), id(4), id(6), id(7)])
                .unwrap();
            assert_eq!(out.tabs, expect, "{extra}");
            let Some(Object::Dict(p)) = s.value(id(3)) else {
                panic!("page");
            };
            let tabs_after = p.get(b"Tabs").cloned();
            let tabs_before = if extra.is_empty() {
                None
            } else {
                Some(Object::Name(Name::from(
                    extra.trim_start_matches("/Tabs /").as_bytes(),
                )))
            };
            assert_eq!(
                tabs_after, tabs_before,
                "/Tabs is read, never written ({extra})"
            );
        }
        assert_eq!(
            PageTabs::ArrayOrder.array_order_governs(),
            ArrayOrderGoverns::Everything
        );
        assert_eq!(
            PageTabs::WidgetOrder.array_order_governs(),
            ArrayOrderGoverns::Widgets
        );
        assert_eq!(
            PageTabs::Absent.array_order_governs(),
            ArrayOrderGoverns::Nothing
        );
        assert_eq!(
            PageTabs::Structure.array_order_governs(),
            ArrayOrderGoverns::Nothing
        );
    }

    /// Page with two widgets (4, 5), a Text note (6) and a `/TrapNet` (7)
    /// last, the trap network carrying `/Version` and an `/AnnotStates`
    /// array parallel to the three non-trap entries.
    fn trapnet_fixture(states: &str) -> Vec<u8> {
        build(
            &[
                "<< /Type /Catalog /Pages 2 0 R >>",
                "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
                "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 300] /Resources << >> \
                 /Annots [4 0 R 5 0 R 6 0 R 7 0 R] >>",
                "<< /Type /Annot /Subtype /Widget /FT /Btn /T (a) /AS /On /Rect [0 0 10 10] >>",
                "<< /Type /Annot /Subtype /Widget /FT /Btn /T (b) /AS /Off /Rect [20 0 30 10] >>",
                "<< /Type /Annot /Subtype /Text /Rect [60 0 70 10] >>",
                &format!(
                    "<< /Type /Annot /Subtype /TrapNet /Rect [0 0 300 300] /Version [] \
                     /AnnotStates {states} >>"
                ),
            ],
            "",
        )
    }

    #[test]
    fn reorder_annotations_pins_a_trap_network_last_and_permutes_annot_states() {
        // Listing the trap network LAST is accepted; it stays in its slot.
        let mut s = session(trapnet_fixture("[/On /Off null]"));
        let out = s
            .reorder_annotations(0, &[id(6), id(5), id(4), id(7)])
            .unwrap();
        assert!(out.trap_net_pinned);
        assert!(out.annot_states_permuted);
        assert_eq!(out.moved, 2, "6 and 4 swapped; 5 stayed; 7 pinned");
        assert_eq!(
            annots_of(&s, id(3)),
            vec![Some(id(6)), Some(id(5)), Some(id(4)), Some(id(7))]
        );
        // /AnnotStates followed: [On Off null] -> [null Off On].
        let Some(Object::Dict(trap)) = s.value(id(7)) else {
            panic!("trap");
        };
        let Some(Object::Array(states)) = trap.get(b"AnnotStates") else {
            panic!("states");
        };
        assert_eq!(
            states,
            &vec![
                Object::Null,
                Object::Name(Name::from(b"Off")),
                Object::Name(Name::from(b"On")),
            ]
        );
        // Omitting it is equally accepted.
        let mut s2 = session(trapnet_fixture("[/On /Off null]"));
        let out2 = s2.reorder_annotations(0, &[id(6), id(5), id(4)]).unwrap();
        assert_eq!(out2.moved, 2);
        // Undo restores both arrays.
        s.undo();
        assert_eq!(
            annots_of(&s, id(3)),
            vec![Some(id(4)), Some(id(5)), Some(id(6)), Some(id(7))]
        );
        let Some(Object::Dict(trap)) = s.value(id(7)) else {
            panic!("trap");
        };
        assert_eq!(
            trap.get(b"AnnotStates"),
            Some(&Object::Array(vec![
                Object::Name(Name::from(b"On")),
                Object::Name(Name::from(b"Off")),
                Object::Null,
            ]))
        );
    }

    #[test]
    fn reorder_annotations_refuses_a_trap_network_anywhere_but_last() {
        let mut s = session(trapnet_fixture("[/On /Off null]"));
        let err = s
            .reorder_annotations(0, &[id(7), id(6), id(5), id(4)])
            .unwrap_err();
        assert!(
            matches!(err, EditError::TrapNetMustStayLast { page_index: 0, id: t } if t == id(7)),
            "{err:?}"
        );
        assert!(!s.is_modified());
    }

    #[test]
    fn reorder_annotations_refuses_a_mismatched_annot_states_array() {
        let mut s = session(trapnet_fixture("[/On /Off]"));
        let err = s
            .reorder_annotations(0, &[id(6), id(5), id(4)])
            .unwrap_err();
        assert!(
            matches!(
                err,
                EditError::AnnotStatesMismatch {
                    page_index: 0,
                    expected: 3,
                    got: 2
                }
            ),
            "{err:?}"
        );
        assert!(!s.is_modified());
    }

    #[test]
    fn reorder_annotations_reindexes_goto_e_targets_into_this_page() {
        // An outline item (8) carries a /GoToE whose first-level target
        // names page 0 by index and annotation index 3 (the Text note, 7).
        // A Link annotation (9) on the page carries one naming the page by
        // REFERENCE and annotation index 0 (widget 4). A third action (10)
        // targets page 1 -- a different page -- and must not move.
        let bytes = build(
            &[
                "<< /Type /Catalog /Pages 2 0 R /Outlines 8 0 R /OpenAction 10 0 R >>",
                "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
                "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 300] /Resources << >> \
                 /Annots [4 0 R 5 0 R 6 0 R 7 0 R 9 0 R] >>",
                "<< /Type /Annot /Subtype /Widget /FT /Tx /T (a) /Rect [0 0 10 10] >>",
                "<< /Type /Annot /Subtype /Widget /FT /Tx /T (b) /Rect [20 0 30 10] >>",
                "<< /Type /Annot /Subtype /Link /Rect [40 0 50 10] >>",
                "<< /Type /Annot /Subtype /Text /Rect [60 0 70 10] >>",
                "<< /Type /Outlines /First 8 0 R /Last 8 0 R /Count 1 \
                 /A << /S /GoToE /T << /R /C /P 0 /A 3 /T << /R /C /P 0 /A 1 >> >> >> >>",
                "<< /Type /Annot /Subtype /Link /Rect [80 0 90 10] \
                 /A << /S /GoToE /T << /R /C /P 3 0 R /A 0 >> >> >>",
                "<< /S /GoToE /T << /R /C /P 1 /A 0 >> >>",
            ],
            "",
        );
        let mut s = session(bytes);
        // Reverse the five: new order 9,7,6,5,4 -> old index 4 becomes 0,
        // old 3 becomes 1, ..., old 0 becomes 4.
        let out = s
            .reorder_annotations(0, &[id(9), id(7), id(6), id(5), id(4)])
            .unwrap();
        assert_eq!(
            out.goto_e_targets_reindexed, 2,
            "outline target + link target"
        );
        let Some(Object::Dict(outline)) = s.value(id(8)) else {
            panic!("outline");
        };
        let Some(Object::Dict(action)) = outline.get(b"A") else {
            panic!("action");
        };
        let Some(Object::Dict(target)) = action.get(b"T") else {
            panic!("target");
        };
        assert_eq!(
            target.get(b"A"),
            Some(&Object::Integer(1)),
            "old index 3 -> new 1"
        );
        // The NESTED target describes the embedded file's page and is untouched.
        let Some(Object::Dict(nested)) = target.get(b"T") else {
            panic!("nested");
        };
        assert_eq!(nested.get(b"A"), Some(&Object::Integer(1)));
        let Some(Object::Dict(link)) = s.value(id(9)) else {
            panic!("link");
        };
        let Some(Object::Dict(la)) = link.get(b"A") else {
            panic!("la");
        };
        let Some(Object::Dict(lt)) = la.get(b"T") else {
            panic!("lt");
        };
        assert_eq!(
            lt.get(b"A"),
            Some(&Object::Integer(4)),
            "old index 0 -> new 4"
        );
        // The other page's target is untouched.
        let Some(Object::Dict(other)) = s.value(id(10)) else {
            panic!("other");
        };
        let Some(Object::Dict(ot)) = other.get(b"T") else {
            panic!("ot");
        };
        assert_eq!(ot.get(b"A"), Some(&Object::Integer(0)));
        // Undo restores the outline's action.
        s.undo();
        let Some(Object::Dict(outline)) = s.value(id(8)) else {
            panic!("outline");
        };
        let Some(Object::Dict(action)) = outline.get(b"A") else {
            panic!("action");
        };
        let Some(Object::Dict(target)) = action.get(b"T") else {
            panic!("target");
        };
        assert_eq!(target.get(b"A"), Some(&Object::Integer(3)));
    }

    #[test]
    fn reorder_annotations_edits_a_sole_owner_indirect_array_in_place() {
        let mut s = session(reorder_fixture("", "8 0 R"));
        let out = s
            .reorder_annotations(0, &[id(7), id(4), id(5), id(6)])
            .unwrap();
        assert!(!out.array_copied);
        assert_eq!(out.moved, 4);
        let dirty = s.dirty_set();
        assert_eq!(dirty.len(), 1, "only the array object changed");
        let Some(Object::Dict(p)) = s.value(id(3)) else {
            panic!("page");
        };
        assert_eq!(
            p.get(b"Annots").and_then(Object::as_reference),
            Some(id(8)),
            "the page still points at its own array"
        );
        assert_eq!(
            annots_of(&s, id(3)),
            vec![Some(id(7)), Some(id(4)), Some(id(5)), Some(id(6))]
        );
    }

    #[test]
    fn reorder_annotations_copies_a_shared_indirect_array_x7() {
        // Two pages share array 6. Reordering page 0 must leave page 1's
        // order alone.
        let bytes = build(
            &[
                "<< /Type /Catalog /Pages 2 0 R >>",
                "<< /Type /Pages /Kids [3 0 R 4 0 R] /Count 2 /MediaBox [0 0 300 300] \
                 /Resources << >> >>",
                "<< /Type /Page /Parent 2 0 R /Annots 6 0 R >>",
                "<< /Type /Page /Parent 2 0 R /Annots 6 0 R >>",
                "<< /Type /Annot /Subtype /Text /Rect [0 0 5 5] >>",
                "[5 0 R 7 0 R]",
                "<< /Type /Annot /Subtype /Text /Rect [10 0 15 5] >>",
            ],
            "",
        );
        let mut s = session(bytes);
        let out = s.reorder_annotations(0, &[id(7), id(5)]).unwrap();
        assert!(out.array_copied);
        assert_eq!(annots_of(&s, id(3)), vec![Some(id(7)), Some(id(5))]);
        assert_eq!(annots_of(&s, id(4)), vec![Some(id(5)), Some(id(7))]);
        let Some(Object::Dict(p1)) = s.value(id(4)) else {
            panic!("p1");
        };
        assert_eq!(
            p1.get(b"Annots").and_then(Object::as_reference),
            Some(id(6))
        );
    }

    #[test]
    fn reorder_annotations_on_a_page_without_annots() {
        let bytes = build(
            &[
                "<< /Type /Catalog /Pages 2 0 R >>",
                "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
                "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 300 300] /Resources << >> >>",
            ],
            "",
        );
        let mut s = session(bytes);
        let out = s.reorder_annotations(0, &[]).unwrap();
        assert_eq!(out.entries, 0);
        assert!(!s.is_modified());
        let err = s.reorder_annotations(0, &[id(9)]).unwrap_err();
        assert!(
            matches!(err, EditError::AnnotsNotAPermutation { expected: 0, .. }),
            "{err:?}"
        );
        let err = s.reorder_annotations(3, &[]).unwrap_err();
        assert!(
            matches!(err, EditError::PageOutOfRange { index: 3, count: 1 }),
            "{err:?}"
        );
    }

    #[test]
    fn reorder_annotations_survives_save_and_reopen() {
        let mut s = session(reorder_fixture("", "[4 0 R 5 0 R 6 0 R 7 0 R]"));
        s.reorder_annotations(0, &[id(6), id(7), id(4), id(5)])
            .unwrap();
        let bytes = s.to_incremental_bytes(&SaveOptions::identity()).unwrap().0;
        let reopened = session(bytes);
        assert_eq!(
            annots_of(&reopened, id(3)),
            vec![Some(id(6)), Some(id(7)), Some(id(4)), Some(id(5))]
        );
        // And the reopened annotations are the originals, not copies.
        let annots = crate::annot::page_annotations(&reopened.graph(), id(3));
        assert_eq!(annots.len(), 4);
        assert_eq!(annots[0].id, Some(id(6)));
    }

    #[test]
    fn encrypted_documents_are_refused_before_authoring_can_be_reached_x10() {
        // Today pdfcer refuses to LOAD an encrypted file at all
        // (`EncryptionUnsupported`), so the `DocumentEncrypted` guard in
        // `add_markup` is a forward-compatible R37 seam, not a path a
        // loadable file reaches. This test pins the load-time refusal so
        // the seam's rationale stays visible: when Pass 5 makes encrypted
        // files loadable, the guard is what keeps authoring from writing
        // plaintext strings into them (X10).
        let bytes = build(
            &[
                "<< /Type /Catalog /Pages 2 0 R >>",
                "<< /Type /Pages /Kids [3 0 R] /Count 1 /MediaBox [0 0 300 300] \
                 /Resources << >> >>",
                "<< /Type /Page /Parent 2 0 R >>",
            ],
            "/Encrypt 9 0 R /ID [<01> <02>] ",
        );
        assert!(
            Document::from_bytes(bytes).is_err(),
            "an encrypted file is refused at load today; the add_markup guard is the Pass-5 seam"
        );
    }

    #[test]
    fn empty_geometry_is_refused() {
        let mut s = session(pdf_without_info());
        let empty_ink = MarkupSpec::Ink {
            strokes: vec![],
            color: Color::Gray(0.0),
            width: 1.0,
        };
        assert!(matches!(
            s.add_markup(0, &empty_ink),
            Err(EditError::EmptyGeometry)
        ));
    }

    /// `Pass 82.1` — the boundary, from BOTH sides, for each subtype.
    ///
    /// Asserting only the refusal would pass against a validator that
    /// refuses everything, and asserting only the acceptance would pass
    /// against the `< 2` rule this Pass replaced. The pair is what pins
    /// the threshold to a specific number.
    #[test]
    fn a_two_vertex_polygon_is_refused_by_name_and_three_is_accepted() {
        let verts = |n: usize| -> Vec<(f64, f64)> {
            (0..n).map(|i| (10.0 * i as f64, 10.0 * i as f64)).collect()
        };
        let poly = |n: usize| MarkupSpec::Polygon {
            vertices: verts(n),
            border: Some(Color::Gray(0.0)),
            interior: None,
            width: 1.0,
        };

        let mut s = session(pdf_without_info());
        // ★ The refusal NAMES the constraint. `EmptyGeometry` here would be
        // a true-ish statement that sends the caller looking for a missing
        // list rather than a short one (R27).
        assert!(matches!(
            s.add_markup(0, &poly(2)),
            Err(EditError::TooFewVertices {
                subtype: "Polygon",
                needed: 3,
                given: 2
            })
        ));

        let mut s = session(pdf_without_info());
        s.add_markup(0, &poly(3))
            .expect("three vertices is a polygon");
    }

    #[test]
    fn a_one_vertex_polyline_is_refused_and_two_is_accepted() {
        let verts = |n: usize| -> Vec<(f64, f64)> {
            (0..n).map(|i| (10.0 * i as f64, 10.0 * i as f64)).collect()
        };
        let line = |n: usize| MarkupSpec::PolyLine {
            vertices: verts(n),
            color: Color::Gray(0.0),
            width: 1.0,
        };

        let mut s = session(pdf_without_info());
        assert!(matches!(
            s.add_markup(0, &line(1)),
            Err(EditError::TooFewVertices {
                subtype: "PolyLine",
                needed: 2,
                given: 1
            })
        ));

        // ★ THE REGRESSION THIS PAIR EXISTS FOR. A two-point PolyLine is a
        // line segment and MUST stay legal — the obvious "fix" for the
        // polygon defect is to raise the shared threshold to 3, which
        // would silently delete the most ordinary PolyLine there is.
        let mut s = session(pdf_without_info());
        s.add_markup(0, &line(2))
            .expect("two vertices is a line segment");
    }

    /// An EMPTY list keeps reporting [`EditError::EmptyGeometry`].
    ///
    /// `Pass 82.1` split one error into two and this pins the split at the
    /// right place: "you passed nothing" and "you passed too few" are
    /// different problems, and the zero case is genuinely the former.
    /// Without this, the new named error would quietly swallow the empty
    /// case and the older, better message for it would be dead code.
    #[test]
    fn an_empty_vertex_list_is_still_empty_geometry_not_too_few_vertices() {
        let mut s = session(pdf_without_info());
        let empty = MarkupSpec::Polygon {
            vertices: vec![],
            border: Some(Color::Gray(0.0)),
            interior: None,
            width: 1.0,
        };
        assert!(matches!(
            s.add_markup(0, &empty),
            Err(EditError::EmptyGeometry)
        ));
    }

    /// `Pass 82.0` — `/I` is a CONTINUOUS range, so a non-integral value
    /// must be accepted.
    ///
    /// This is the test that would have failed against the roadmap's own
    /// acceptance criterion, which said `/I` was the enumeration
    /// `{0, 1, 2}`. Table 167 types it `number`, "in the range 0 to 2",
    /// identically in both editions.
    #[test]
    fn a_fractional_cloud_intensity_is_accepted_because_the_range_is_continuous() {
        let mut s = session(pdf_without_info());
        s.add_markup(0, &cloud_spec(1.5))
            .expect("1.5 is in the range 0 to 2");
    }

    #[test]
    fn cloud_intensity_outside_zero_to_two_is_refused_by_name() {
        for bad in [-0.001, 2.001, f64::NAN, f64::INFINITY] {
            let mut s = session(pdf_without_info());
            assert!(
                matches!(
                    s.add_markup(0, &cloud_spec(bad)),
                    Err(EditError::BorderEffectIntensityOutOfRange { .. })
                ),
                "intensity {bad} should be refused by name"
            );
        }
        // Both endpoints are IN the range — the boundary from the other
        // side, so this cannot pass against a validator that refuses
        // everything.
        for good in [0.0, 2.0] {
            let mut s = session(pdf_without_info());
            s.add_markup(0, &cloud_spec(good))
                .expect("endpoints are inside a closed range");
        }
    }

    /// A two-vertex cloud is refused with `Cloud` in the message, not
    /// `Polygon` — the caller asked for a cloud and should be told about
    /// the thing they asked for (`Pass 82.1` acceptance 2 + R27).
    #[test]
    fn a_two_vertex_cloud_is_refused_by_name() {
        let mut s = session(pdf_without_info());
        let spec = MarkupSpec::Cloud {
            vertices: vec![(0.0, 0.0), (50.0, 0.0)],
            border: Some(Color::Gray(0.0)),
            interior: None,
            width: 1.0,
            intensity: 1.0,
        };
        assert!(matches!(
            s.add_markup(0, &spec),
            Err(EditError::TooFewVertices {
                subtype: "Cloud",
                needed: 3,
                given: 2
            })
        ));
    }

    /// ★ The cloud must actually BULGE, and its `/Rect` must contain the
    /// bulge.
    ///
    /// Asserting only that the appearance contains `c` operators would
    /// pass against a stream that emitted curves along the straight edge
    /// and drew no cloud at all. This asserts the geometric consequence
    /// instead: the annotation rectangle is strictly larger than the
    /// vertex hull, which is only true if something was drawn outside it.
    /// That is also the defect that makes a baked cloud render with its
    /// bumps sliced flat — a `/BBox` that clips its own content.
    #[test]
    fn a_cloud_rect_grows_to_contain_the_bulge() {
        use crate::annot_author::build_appearance;
        let plain = build_appearance(&MarkupSpec::Polygon {
            vertices: vec![(20.0, 20.0), (120.0, 20.0), (120.0, 90.0)],
            border: Some(Color::Gray(0.0)),
            interior: None,
            width: 1.0,
        });
        let cloudy = build_appearance(&cloud_spec(1.0));
        assert!(
            cloudy.rect.llx < plain.rect.llx && cloudy.rect.ury > plain.rect.ury,
            "cloud rect {:?} must exceed the plain polygon rect {:?}",
            cloudy.rect,
            plain.rect
        );
        // And the appearance is genuinely curved rather than a polyline.
        assert!(
            cloudy.ap_content.windows(2).any(|w| w
                == b"c
") || cloudy.ap_content.ends_with(b"c"),
            "a cloud appearance must contain cubic segments"
        );
    }

    /// `/BE` and `/RD` land in the annotation dictionary, and `/Subtype`
    /// stays `/Polygon` — there is no `/Cloud` subtype in ISO 32000.
    #[test]
    fn a_cloud_writes_be_on_a_polygon_subtype() {
        use crate::annot_author::build_appearance;
        let a = build_appearance(&cloud_spec(2.0));
        let subtype = a.annot.get(b"Subtype").expect("subtype");
        assert!(
            matches!(subtype, Object::Name(n) if n.as_bytes() == b"Polygon"),
            "a cloud is a Polygon carrying /BE, not its own subtype"
        );
        let Some(Object::Dict(be)) = a.annot.get(b"BE") else {
            panic!("/BE must be written");
        };
        assert!(matches!(be.get(b"S"), Some(Object::Name(n)) if n.as_bytes() == b"C"));
        assert!(matches!(be.get(b"I"), Some(Object::Real(v)) if (*v - 2.0).abs() < 1e-9));
    }

    /// A cloudy `Square` keeps `/Subtype /Square`, gains `/BE`, and
    /// records `/RD` so the box the operator drew stays recoverable.
    #[test]
    fn a_cloudy_square_records_rd_so_the_drawn_box_is_recoverable() {
        use crate::annot_author::build_appearance;
        let rect = Rect {
            llx: 30.0,
            lly: 40.0,
            urx: 130.0,
            ury: 110.0,
        };
        let a = build_appearance(&MarkupSpec::Square {
            rect,
            border: Some(Color::Gray(0.0)),
            interior: None,
            border_width: 1.0,
            border_effect: Some(1.0),
        });
        assert!(
            matches!(a.annot.get(b"Subtype"), Some(Object::Name(n)) if n.as_bytes() == b"Square")
        );
        let Some(Object::Array(rd)) = a.annot.get(b"RD") else {
            panic!("/RD must be written alongside /BE");
        };
        assert_eq!(rd.len(), 4);
        let Object::Real(inset) = rd[0] else {
            panic!("/RD entries are numbers")
        };
        // Rect minus RD recovers the square the caller asked for.
        assert!((a.rect.llx + inset - rect.llx).abs() < 1e-9);
        assert!((a.rect.ury - inset - rect.ury).abs() < 1e-9);
    }

    fn cloud_spec(intensity: f64) -> MarkupSpec {
        MarkupSpec::Cloud {
            vertices: vec![(20.0, 20.0), (120.0, 20.0), (120.0, 90.0)],
            border: Some(Color::Gray(0.0)),
            interior: None,
            width: 1.0,
            intensity,
        }
    }

